#!/usr/bin/env python3
"""Generated by stone render. Do not edit: change .cornerstone/config.yaml and render again.

Check K22: fail if a tracked instruction file has text that can make an agent harm the repo (D89).
It finds a package install from a registry, a download piped to a shell, an API base URL or
proxy override, a URL to a host that is not in `instruction_text.hosts`, and hidden Unicode.
An HTML comment gives a warning. A heading with `waiver (K22)` and text under it in the PR body
passes the findings, with a notice. A package in `instruction_text.packages` passes.
Run it in the repo root. Usage: instruction_text.py [--body FILE|-] [--format text|github]
"""

import argparse
import re
import subprocess
import sys
from pathlib import Path

sys.dont_write_bytecode = True  # no __pycache__ folder in .cornerstone/lib
sys.path.insert(0, str(Path(__file__).resolve().parent.parent / "lib"))
try:
    from path_match import covers
except Exception:  # noqa: BLE001 - a missing or broken module must fail the check, not pass it
    print("K22: .cornerstone/lib/path_match.py is missing or broken. Run stone render.")
    sys.exit(1)

INSTRUCTION_FILES = ["**/[Aa][Gg][Ee][Nn][Tt][Ss].[Mm][Dd]", "**/[Cc][Ll][Aa][Uu][Dd][Ee].[Mm][Dd]", "**/[Cc][Ll][Aa][Uu][Dd][Ee].[Ll][Oo][Cc][Aa][Ll].[Mm][Dd]"]
HOSTS = ["brawblan.github.io"]
PACKAGES = []

INSTALL = re.compile(
    r"\b(?:npm|pnpm|yarn|bun)\s+(?:install|i|add)\b(?P<a>[^\n`|;&]*)"
    r"|\b(?:npx|bunx|pnpx)\s+(?P<b>[^\n`|;&]*)"
    r"|\b(?:pnpm|yarn)\s+dlx\s+(?P<c>[^\n`|;&]*)"
    r"|\b(?:pip3?|pipx|uv\s+pip|uv\s+tool)\s+(?:install|run)\b(?P<d>[^\n`|;&]*)"
    r"|\buv\s+add\b(?P<e>[^\n`|;&]*)"
    r"|\b(?:gem|cargo|go|brew)\s+install\b(?P<f>[^\n`|;&]*)"
    r"|\bapt(?:-get)?\s+install\b(?P<g>[^\n`|;&]*)")
PIPE_TO_SHELL = re.compile(r"\b(?:curl|wget|iwr|irm)\b[^\n`]*\|\s*(?:sudo\s+)?(?:ba|z|da)?sh\b"
                           r"|\b(?:curl|wget|iwr|irm)\b[^\n`]*\|\s*(?:iex|python3?|node)\b")
OVERRIDE = re.compile(r"\b[A-Z][A-Z0-9_]*_(?:BASE_URL|API_URL|ENDPOINT)\b"
                      r"|\b(?:HTTPS?|ALL)_PROXY\b", re.IGNORECASE)
URL = re.compile(r"\b(?:https?|wss?|ftp)://([^/\s)>\]`\"'<]+)", re.IGNORECASE)
HIDDEN = re.compile("[​-‏‪-‮⁠-⁤⁦-⁩﻿"
                    "\U000e0000-\U000e007f]")
COMMENT = re.compile(r"<!--(?!\s*ste-ignore\s*-->)")
OPTION_WITH_PATH = {"-r", "--requirement", "-c", "--constraint", "-e", "--editable"}
WAIVER = re.compile(r"^#{1,6}[ \t]+.*waiver \(k22\)", re.IGNORECASE)


def registry_packages(args: str) -> list[str]:
    """Return each argument that names a registry package, not an option or a local path."""
    names, skip = [], False
    for token in args.split():
        if skip:
            skip = False
            continue
        if token in OPTION_WITH_PATH:
            skip = True
            continue
        local = token.startswith((".", "/", "~", "-", "$", "<"))  # a path, option, or placeholder
        if not local and token.strip("'\"") not in PACKAGES:
            names.append(token)
    return names


def host_allowed(host: str) -> bool:
    host = host.rsplit("@", 1)[-1].split(":", 1)[0].lower().rstrip(".")
    return any(host == item or host.endswith("." + item) for item in HOSTS)


def line_findings(line: str) -> list[tuple[str, str]]:
    """Return (level, message) for each finding in one line."""
    found = []
    for match in INSTALL.finditer(line):
        args = next(group for group in match.groups() if group is not None)
        if match.group("b") is not None or match.group("c") is not None:
            # npx and dlx run one package. The other words are arguments of that program.
            args = next((word for word in args.split() if not word.startswith("-")), "")
        names = registry_packages(args)
        if names:
            found.append(("error", f"installs a package from a registry: {', '.join(names)}. "
                          "Add it to instruction_text.packages if a human trusts it."))
    if PIPE_TO_SHELL.search(line):
        found.append(("error", "pipes a download to a shell or an interpreter."))
    for match in OVERRIDE.finditer(line):
        found.append(("error", f"names {match.group(0)}, which can send the traffic of the "
                      "agent to another host."))
    for match in URL.finditer(line):
        if not host_allowed(match.group(1)):
            found.append(("error", f"has a URL to {match.group(1)}. The host is not in "
                          "instruction_text.hosts."))
    for match in HIDDEN.finditer(line):
        found.append(("error", f"has the hidden character U+{ord(match.group(0)):04X}."))
    if COMMENT.search(line):
        found.append(("warning", "has an HTML comment. A reader does not see it, but an agent "
                      "reads it."))
    return found


def instruction_files() -> list[str]:
    run = subprocess.run(["git", "ls-files", "-z"], capture_output=True, text=True, check=True)
    return sorted(path for path in run.stdout.split("\0") if path and covers(INSTRUCTION_FILES, path))


def has_waiver(body: str) -> bool:
    lines = body.splitlines()
    for number, line in enumerate(lines):
        if WAIVER.match(line):
            text = []
            for after in lines[number + 1:]:
                if after.lstrip().startswith("#"):
                    break
                text.append(after.strip())
            content = " ".join(item for item in text if item)
            if content and content.lower() not in {"none", "tbd", "n/a"}:
                return True
    return False


def main(argv: list[str]) -> int:
    parser = argparse.ArgumentParser(prog="instruction_text.py")
    parser.add_argument("--body", help="The PR body: a file, or - for stdin.")
    parser.add_argument("--format", choices=["text", "github"], default="text")
    args = parser.parse_args(argv)
    body = ""
    if args.body == "-":
        body = sys.stdin.read()
    elif args.body:
        body = Path(args.body).read_text(encoding="utf-8")
    waived = has_waiver(body)
    errors = warnings = 0
    for path in instruction_files():
        text = Path(path).read_text(encoding="utf-8", errors="replace")
        for number, line in enumerate(text.splitlines(), start=1):
            for level, message in line_findings(line):
                if level == "error" and waived:
                    level = "notice"
                errors += level == "error"
                warnings += level == "warning"
                if args.format == "github":
                    print(f"::{level} file={path},line={number}::K22: {message}")
                else:
                    print(f"{path}:{number}: {level}: K22: {message}")
    if waived:
        print("K22: notice: the PR body has a Waiver (K22) section. A human reviews each finding.")
    print(f"K22: {errors} error(s), {warnings} warning(s).")
    return 1 if errors else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
